"""
Automated Policy Document Extraction Script
Queries public government APIs and tracks changes over time.
"""

import json
import os
import time
from datetime import datetime
from typing import Dict, List, Any
import requests
from dataclasses import dataclass
import yaml


@dataclass
class PolicyDocument:
    """Data structure for storing policy document metadata."""
    title: str
    url: str
    document_id: str
    agency: str
    publication_date: str
    summary: str
    archived: bool = False
    archived_date: str = None


class PolicyDataExtractor:
    """Main class for extracting and managing policy documents from government APIs."""

    def __init__(self, api_config_path: str = None):
        self.api_config = self._load_config(api_config_path)
        self.stored_data = []
        self.last_run_export = None

    def _load_config(self, config_path: str) -> Dict:
        """Load API configuration from YAML file or use defaults."""
        if config_path and os.path.exists(config_path):
            with open(config_path, 'r') as f:
                return yaml.safe_load(f)
        return self._get_default_config()

    def _get_default_config(self) -> Dict:
        """Return default API configuration for common government sources."""
        return {
            'data_gov': {
                'base_url': 'https://api.data.gov',
                'endpoints': {
                    'search': '/catalogue/search/api',
                    'recent': '/catalogue/search/api?sort_direction=DESC&sort_field=updateDate&results_per_page=50'
                },
                'headers': {
                    'User-Agent': 'PolicyResearcher/1.0'
                }
            },
            'regulations_gov': {
                'base_url': 'https://www.regulations.gov',
                'endpoint': '/search.json',
                'headers': {
                    'User-Agent': 'PolicyResearcher/1.0'
                }
            },
            'scheduled_tasks': [
                {'source': 'data_gov', 'interval_hours': 24},
                {'source': 'regulations_gov', 'interval_hours': 12}
            ],
            'export_path': '/home/user/project/policy_data_export.json'
        }

    def fetch_documents(self, source: str) -> List[PolicyDocument]:
        """Fetch policy documents from specified government API source."""
        config = self.api_config[source]
        all_documents = []

        try:
            url = self._get_source_url(source)
            headers = config.get('headers', {})

            if source == 'data_gov':
                response = requests.get(url, headers=headers, timeout=30)
                response.raise_for_status()
                data = response.json()

                for item in data.get('records', data.get('data', [])):
                    doc = self._parse_data_gov_doc(item, url)
                    if doc:
                        all_documents.append(doc)
            elif source == 'regulations_gov':
                params = {**config, 'q': 'policy'}
                params['limit'] = 50 if hasattr(config, 'limit') else 50
                response = requests.get(url, params=params, headers=headers, timeout=30)
                response.raise_for_status()
                data = response.json()

                for item in data.get('results', []):
                    doc = self._parse_regulations_doc(item, url)
                    if doc:
                        all_documents.append(doc)
        except requests.RequestException as e:
            print(f"Error fetching from {source}: {e}")
            return []
        except json.JSONDecodeError as e:
            print(f"JSON parsing error from {source}: {e}")
            return []

        return all_documents

    def _parse_data_gov_doc(self, item: Dict, base_url: str) -> PolicyDocument:
        """Parse a data.gov document into PolicyDocument structure."""
        return PolicyDocument(
            title=item.get('title', ''),
            url=f"{base_url}/{item.get('path', '')}",
            document_id=item.get('identifier', ''),
            agency=item.get('publisher', {}).get('name', 'Unknown'),
            publication_date=item.get('datePosted', item.get('publishedDateTime', '')),
            summary=item.get('description', '')[:500].replace('\n', ' ')
        )

