        else:
            source_config = self.config['api_sources'][source]

        documents = []
        base_url = source_config.get('base_url', '')
        enabled = source_config.get('enabled', True)

        if not enabled:
            return documents

        try:
            if source == 'data_gov':
                docs = self._fetch_data_gov(source_config)
            elif source == 'regulations_gov':
                docs = self._fetch_regulations_gov(source_config)
            else:
                raise ValueError(f"Unknown source: {source}")

            documents.extend(docs)
