            print(f"data.gov API error: {response.status_code}")
            return docs

        data = response.json()
        self.process_api_response(data, 'data_gov', search_url, docs)
        return docs

    def _fetch_regulations_gov(self, config: Dict) -> List[PolicyDocument]:
        """Fetch documents from regulations.gov API."""
        docs = []
        search_url = config['base_url'] + '/search.json?limit=50'
        params = {'q': 'policy', 'result_type': 'most_recent'}

        response = requests.get(search_url, params=params, timeout=30,
                                headers=self.get_api_headers('regulations_gov'))

        if not response.ok:
            print(f"regulations.gov API error: {response.status_code}")
            return docs

        data = response.json()
        self.process_api_response(data, 'regulations_gov', search_url, docs)
        return docs

    def process_api_response(self, data: dict, source: str, base_url: str, docs: List[PolicyDocument]):
        """Process API response and convert to PolicyDocument objects."""
        records = data.get('records', data.get('data', data.get('results', [{}])) if isinstance(data, dict) else [])
        all_seen = self.seen_ids.get(source, set())

        for record in records:
            doc_id = self._get_document_id(record, source)
            if doc_id in all_seen:
