            all_seen.add(doc_id)

            # Extract fields with fallbacks for different API structures
            title = record.get('title') or record.get('name') or ''
            document_path = record.get('path') or record.get('accession_number') or ''

            # Construct URL
            if source == 'data_gov':
                url = f"{base_url}/{document_path}"
            else:
                url = f"{base_url}/{document_path}"

            doc = PolicyDocument(
                title=title,
                url=url,
                document_id=doc_id,
                agency=self._get_agency(record, source) or 'Unknown',
                publication_date=self._get_date(record, source) or '',
                summary=self._get_summary(record, source)[:500].replace('\n', ' ').strip()
            )
