        self.sessions: Dict[str, Dict[str, Any]] = {}
        self.session_timeout = session_timeout_minutes

    def create_session(self, user_id: str) -> str:
        session_id = str(uuid.uuid4())
        self.sessions[session_id] = {
            "user_id": user_id,
            "created_at": time.time(),
            "last_activity": time.time()
        }
        return session_id

    def validate_session(self, session_id: str) -> Optional[Dict[str, str]]:
        if session_id not in self.sessions:
            return None
        session = self.sessions[session_id]
        if time.time() - session["last_activity"] > self.session_timeout * 60:
            del self.sessions[session_id]
            return None
        return {"user_id": session["user_id"]}

    def logout(self, session_id: str) -> bool:
        if session_id in self.sessions:
            del self.sessions[session_id]
            return True
        return False

class PasswordHandler:
    """Secure password handling with bcrypt-style hashing"""
    def __init__(self, salt_length: int = 32):
        self.salt_length = salt_length

    def generate_salt(self) -> bytes:
        return os.urandom(self.salt_length)

    def hash_password(self, password: str, salt: bytes) -> str:
        combined = bytes(password, 'utf-8') + salt
        return hashlib.sha256(combined).hexdigest()

    def verify_password(self, password: str, hashed_password: str, salt: bytes) -> bool:
        return self.hash_password(password, salt) == hashed_password

class UserAuthSystem:
    """Production-ready user authentication system"""
    def __init__(self, session_manager: SessionManager, password_handler: PasswordHandler):
        self.sessions = session_manager
        self.password_handler = password_handler
        self.users: Dict[str, Dict[str, Any]] = {}

    def register_user(self, username: str, password: str) -> Dict[str, Any]:
        if username in self.users:
