Government Data Automation Script
This script automates data extraction from public government databases to analyze policy trends.
It queries APIs like data.gov and regulations.gov, parses results, stores them structurally,
and can be scheduled to track changes over time.
"""

import requests
import json
import csv
import os
from datetime import datetime
from pathlib import Path
import schedule
import time
import sys

# Configuration
API_BASE_URLS = {
    "data_gov": "https://api.data.gov/search",
    "regulations_gov": "https://regulations.gov/api/v1/document"
}
OUTPUT_DIR = Path("./output")
OUTPUT_DIR.mkdir(exist_ok=True)

class GovernmentDataExtractor:
    def __init__(self, api_key=None):
        self.api_key = api_key
        self.headers = {}
        if api_key:
            self.headers["Authorization"] = f"Bearer {api_key}"

    def fetch_data_gov(self, topic=None, limit=100):
        """Fetch data from data.gov API"""
        url = API_BASE_URLS["data_gov"]
        if topic:
            params = {
                "q": topic,
                "rows": limit,
                "start": 0
            }
        else:
            params = {"rows": limit}

        try:
            response = requests.get(url, params=params, headers=self.headers, timeout=30)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as e:
            print(f"Error fetching data.gov: {e}")
            return None

    def fetch_regulations_gov(self):
        """Fetch documents from regulations.gov"""
        url = API_BASE_URLS["regulations_gov"]
        try:
            response = requests.get(url, headers=self.headers, timeout=30)
            response.raise_for_status()
            return response.json()
        except requests.RequestException as e:
            print(f"Error fetching regulations.gov: {e}")
            return None

    def parse_results(self, data_sources):
        """Parse and structure results from different sources"""
        structured_data = []
        timestamp = datetime.now().isoformat()

        for source, data in data_sources.items():
            if data:
                for item in data.get('results', []):
                    structured_item = {
                        "source": source,
                        "timestamp_collected": timestamp,
                        **item
                    }
                    structured_data.append(structured_item)

        return structured_data

    def store_results(self, structured_data, output_format="json"):
        """Store structured data to file"""
        filename = f"data_{datetime.now().strftime('%Y%m%d_%H%M%S')}"

        if output_format == "json":
            filepath = OUTPUT_DIR / f"{filename}.json"
            with open(filepath, 'w') as f:
                json.dump(structured_data, f, indent=2)
            print(f"Data stored to {filepath}")
        elif output_format == "csv":
            filepath = OUTPUT_DIR / f"{filename}.csv"
            if structured_data:
                with open(filepath, 'w', newline='') as f:
                    writer = csv.DictWriter(f, fieldnames=structured_data[0].keys())
                    writer.writeheader()
                    writer.writerows(structured_data)
            print(f"Data stored to {filepath}")
        else:
            print("Unsupported output format.")

def run_extraction(topic=None):
    """Main extraction function"""
    extractor = GovernmentDataExtractor()
    print("Starting government data extraction...")

    data_sources = {
        "data.gov": extractor.fetch_data_gov(topic)
    }

    if topic:
        print(f"Extracting data for topic: {topic}")
    else:
        print("Extracting general data.")

    structured_data = extractor.parse_results(data_sources)
    extractor.store_results(structured_data, "json")
    return structured_data

def scheduled_extraction(topic=None):
    """Schedule extraction to run periodically"""
    # Every hour at the top of the hour
    schedule.every().hour.at("00").do(run_extraction, topic=topic)

    print("Scheduler started. Check logs for updates.")
    while True:
        schedule.run_pending()
        time.sleep(60)

if __name__ == "__main__":
    # Check for topic argument
    topic = sys.argv[1] if len(sys.argv) > 1 else None

    run_extraction(topic)

    # Optionally run as a scheduled task
    # scheduled_extraction(topic)
