    except Exception as e:
        print(f"Extraction run failed: {e}")
        return False

def main():
    # Simple command-line entry point for cron usage
    if len(sys.argv) > 1:
        interval_minutes = sys.argv[1]
    else:
        interval_minutes = 1440  # Default: 24 hours

    print(f"Scheduler started. Interval: {interval_minutes} minutes.")
