            return publishers.get('name', 'Unknown') if publishers else 'Unknown'
        elif source == 'regulations_gov':
            agencies = record.get('agencies', []) or record.get('agencies', [])
            for agency in agencies or []:
                return agency.get('agency_desc', 'Unknown')
            return 'Unknown'
        return 'Unknown'

    def _get_date(self, record: dict, source: str) -> str:
        """Extract publication/updated date from API response."""
        if source == 'data_gov':
            return record.get('datePosted', record.get('publishedDateTime', record.get('date', '')))
        elif source == 'regulations_gov':
            return record.get('updated_at', record.get('updated_on', record.get('date_accessed', '')))
        return record.get('date', '') or ''

    def _get_summary(self, record: dict, source: str) -> str:
        """Extract summary from API response."""
        if source == 'data_gov':
            return record.get('description', record.get('abstract', ''))
        elif source == 'regulations_gov':
            desc = record.get('description', {})
            return desc.get('description', record.get('title_or_subject', ''))
        return record.get('summary', record.get('title', ''))

    def save_documents(self, docs: List[PolicyDocument], source: str):
        """Save documents to export path."""
        self.exports[source] = docs

        all_exports = []
        for src in self.VALID_SOURCES:
            all_exports.extend(self.exports.get(src, []))

        if all_exports:
            self.export_data(all_exports)
            self.seen_ids = {src: set(self.exports.get(src, [])) for src in self.VALID_SOURCES}

    def export_data(self, docs: List[PolicyDocument]):
        """Export documents to JSON file."""
        timestamp = datetime.now().isoformat()
        path = self.config.get('export_path', '/home/user/project/policy_data_export.json')

        data = {
            'export_timestamp': timestamp,
            'source': 'mixed',
            'record_count': len(docs),
            'records': [{k: v for k, v in asdict(d).items() if v is not None and v != ''}
                       for d in docs]
        }

        try:
            with open(path, 'w') as f:
                json.dump(data, f, indent=2, default=str)
            print(f"Exported {len(docs)} documents to {path}")
        except Exception as e:
            print(f"Failed to export data: {e}")

    def run_job(self, source: str):
        """Run a single extraction job."""
        print(f"\n[{datetime.now().isoformat()}] Running extraction for {source}...")
        docs = self.fetch_documents(source)
        self.save_documents(docs, source)
        print(f"Completed extraction for {source}: {len(docs)} new documents.")
        return len(docs)

    def run_periodic(self, job_configs: List[Dict] = None):
        """Run extraction jobs periodically based on a schedule."""
        if job_configs is None:
            job_configs = self.config.get('schedule', [])

        if not job_configs:
            # Default behavior
            job_configs = [
                {'source': 'data_gov', 'interval_hours': 24},
                {'source': 'regulations_gov', 'interval_hours': 12}
            ]

        while not self.stopped.is_set():
            for job in job_configs:
                if not self.stopped.is_set():
                    source = job.get('source', 'data_gov')
                    interval = job.get('interval_hours', 24)
                    print(f"\nProcessing job: {source} every {interval}h")
                    docs = self.run_job(source)

                if not self.stopped.is_set():
                    print(f"Waiting {interval} hours for next cycle...")
                    time.sleep(interval * 3600)

    def run_once(self, source: str):
        """Run a single extraction and exit."""
        self.run_job(source)


def main():
    """Main entry point."""
    parser = argparse.ArgumentParser(description='Automated Policy Document Extraction')
    parser.add_argument('--config', '-c', default='/home/user/project/api_config.yaml',
                       help='Path to configuration file')
    parser.add_argument('--source', '-s', choices=['data_gov', 'regulations_gov', 'all'],
                       default='data_gov', help='Data source to extract')
    parser.add_argument('--once', '-o', action='store_true',
                       help='Run once and exit (default behavior)')
    parser.add_argument('--periodic', '-p', type=int, default=0,
                       help='Run in periodic mode, interval in seconds')
    parser.add_argument('--interval', '-i', type=int,
                       default=3600, help='Interval between runs in seconds (for periodic mode)')

    args = parser.parse_args()

    scheduler = PolicyScheduler(args.config)
    scheduler.load_config(args.config)

    if args.source == 'all':
        for source in ['data_gov', 'regulations_gov']:
            if args.once:
                scheduler.run_job(source)
            else:
                scheduler.exports[source] = []
                scheduler.seen_ids[source] = set()
    else:
        scheduler.run_job(args.source)

    if args.once:
        print("\nCron job completed.")
    elif args.periodic:
        print(f"Running in periodic mode with {args.interval}s interval. Press Ctrl+C to stop.")
        scheduler.run_periodic()


