    def __init__(self, secret_key='default_secret_key_change_in_production', algorithm='HS256'):
        self.secret_key = secret_key
        self.algorithm = algorithm
        self.users = {}
        self.sessions = {}

    def hash_password(self, password):
        salt = uuid.uuid4().hex
        pwd_hash = hashlib.pbkdf2_hmac('sha512', password.encode('utf-8'), salt.encode('utf-8'), 480000)
        return (salt, pwd_hash.hex())

