        hash_compare = hashlib.pbkdf2_hmac('sha512', password.encode('utf-8'), salt.encode('utf-8'), 480000)
        return hash_compare.hex() == hash_val

    def register_user(self, username, password):
        if username in self.users:
            raise ValueError('Username already exists')
        salt, password_hash = self.hash_password(password)
        self.users[username] = {'password_hash': (salt, password_hash), 'created_at': datetime.datetime.utcnow().isoformat()}
